e5326b4b2e9ccfa4e2f622630942e3a6:
query studentDetailQuery(
  $mnumber: String!
  $term: String!
  $year: Int!
) {
  studentsSingle(where: {mnumber: {eq: $mnumber}}) {
    first_name
    last_name
    middle_name
    suffix
    email
    birthdate
    gender
    cell_phone
    race
    residency
    citizenship
    mnumber
    termInfo: academic_info(term: $term, year: $year) {
      admit_code
      academic_standing {
        code
        description
      }
      admit_term {
        code
        description
      }
      admit_year
      msu_attempted_hours
      msu_earned_hours
      msu_gpa
      msu_quality_points
      overall_attempted_hours
      overall_earned_hours
      overall_gpa
      overall_quality_points
    }
    gpaTrend: academic_info {
      msu_gpa
      overall_gpa
      term {
        code
        description
      }
      year
    }
    advisors {
      advisor_mnumber
      term {
        code
        description
      }
      year
      advisor {
        first_name
        last_name
        mnumber
        user {
          email
        }
      }
    }
    programs {
      term {
        code
        description
      }
      year
      type
      level
      program {
        code
        description
      }
    }
  }
}

